    verificar((int)flujo_fila($bd,'SELECT d.numero_atenciones FROM informe_individual d JOIN informes i ON i.cod_informe=d.cod_informe WHERE i.numero_ficha=?',[$ficha])['numero_atenciones']===3,'Acepta manipulación del conteo individual.');
    $inicioMes=date('Y-m-01');$ultimoPrevio=date('Y-m-d',strtotime($inicioMes.' -1 day'));
