} catch(Throwable $e) {fwrite(STDERR,$e->getMessage()."\n".$e->getTraceAsString()."\n");$fallo=true;}
finally {if($bd instanceof mysqli)$bd->close();if($admin instanceof mysqli){$admin->query("DROP DATABASE IF EXISTS `$base`");$admin->close();}}
exit($fallo?1:0);
